#include "window.h"
#include <QtWidgets>
#include <QSettings>
#include <QLibrary>
#include <source_location>
#include <iostream>
struct QuietVoice:SpeechBackend{void configure(const SpeechSettings&)override{}void speak(const QString&,const std::atomic_bool&)override{}};
struct IntegrationChecks {
 static void require(bool value,std::source_location at=std::source_location::current()){if(!value)throw std::runtime_error("SDR UI line "+std::to_string(at.line()));}
 static void run(bool physical){QTemporaryDir temp;require(temp.isValid());if(!physical){auto root=QCoreApplication::applicationDirPath();qputenv("POCSAG_TEST_RTL_LIBRARY",(root+"/mock_rtl.dll").toUtf8());qputenv("POCSAG_TEST_AIRSPY_LIBRARY",(root+"/mock_airspy.dll").toUtf8());qputenv("POCSAG_TEST_AIRSPYHF_LIBRARY",(root+"/mock_airspy.dll").toUtf8());qputenv("POCSAG_TEST_SOAPY_LIBRARY",temp.filePath("absent.dll").toUtf8());}
 QString qa=qEnvironmentVariable("POCSAG_QA_DIR");if(!qa.isEmpty())QDir().mkpath(qa);Window w(temp.path(),std::make_unique<QuietVoice>());w.show();w.resize(1200,760);require(w.findChild<QAction*>("sdrDeviceManagerAction"));
 for(bool dark:{false,true}){w.findChild<QAction*>(dark?"themeDark":"themeGlacier")->trigger();std::exception_ptr error;QTimer::singleShot(150,&w,[&]{auto d=qobject_cast<QDialog*>(QApplication::activeModalWidget());try{require(d&&d->objectName()=="sdrDeviceManager");auto table=d->findChild<QTableWidget*>("sdrApiDevices");require(table&&table->columnCount()==5);if(!physical)require(table->rowCount()>=5);auto test=d->findChild<QPushButton*>("testSdrDevice");require(test&&test->isVisible()&&d->rect().contains(test->mapTo(d,QPoint(test->width()-1,test->height()-1))));auto refresh=d->findChild<QPushButton*>("refreshSdrDevices");refresh->click();require(!w.radio_.isRunning());if(physical&&!dark&&QApplication::arguments().contains("--test-iq")){int row=-1;for(int i=0;i<table->rowCount();++i)if(table->item(i,0)->toolTip().startsWith("rtl:"))row=i;require(row>=0);table->selectRow(row);d->findChild<QPushButton*>("sdrCapabilities")->click();require(d->findChild<QPlainTextEdit*>("sdrTestResult")->toPlainText().contains("gains interrogés"));test->click();require(d->findChild<QPlainTextEdit*>("sdrTestResult")->toPlainText().contains("Réception IQ vérifiée"));require(w.all_->rowCount()==0&&!w.radio_.isRunning());}if(!qa.isEmpty())d->grab().save(qa+(dark?"/sdr-manager-dark.png":"/sdr-manager-glacier.png"));auto tabs=d->findChild<QTabWidget*>();tabs->setCurrentIndex(1);if(!qa.isEmpty())d->grab().save(qa+(dark?"/sdr-usb-dark.png":"/sdr-usb-glacier.png"));tabs->setCurrentIndex(2);require(!d->findChild<QPlainTextEdit*>("sdrDiagnostics")->toPlainText().isEmpty());tabs->setCurrentIndex(3);auto library=d->findChild<QLineEdit*>("soapyRuntimeLibrary");auto modules=d->findChild<QLineEdit*>("soapyRuntimeModules");library->setText(temp.filePath("missing.dll"));d->findChild<QPushButton*>("saveSoapyRuntime")->click();require(QSettings(w.settingsFile_,QSettings::IniFormat).value("sdr/soapyLibrary").toString().isEmpty());library->setText(QCoreApplication::applicationDirPath()+"/mock_airspy.dll");modules->setText(temp.path());d->findChild<QPushButton*>("saveSoapyRuntime")->click();require(QSettings(w.settingsFile_,QSettings::IniFormat).value("sdr/soapyLibrary").toString()==library->text());library->clear();modules->clear();d->findChild<QPushButton*>("saveSoapyRuntime")->click();d->reject();}catch(...){error=std::current_exception();if(d)d->reject();}});w.findChild<QAction*>("sdrDeviceManagerAction")->trigger();if(error)std::rethrow_exception(error);}
 // A missing remembered receiver must not switch to another connected device.
 w.devices_->addItem("Remembered absent","airspy:absent");w.devices_->setCurrentIndex(w.devices_->count()-1);w.storePreferences();w.reloadDevices();require(w.devices_->currentData().toString()=="airspy:absent");auto model=qobject_cast<QStandardItemModel*>(w.devices_->model());require(model&&!model->item(w.devices_->currentIndex())->isEnabled());require(!w.radio_.isRunning());
 }
};
int main(int argc,char** argv){QApplication app(argc,argv);app.setOrganizationName("Isolated-SDR-UI-QA");app.setApplicationName("Isolated");try{IntegrationChecks::run(app.arguments().contains("--physical-inventory"));std::cout<<"PASS SDR manager themes, API/USB distinction, controls, runtime persistence, no user data, absent identity preserved\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
